hardware_fan_persist_note: "يستمر حتى إعادة تشغيل PS5. لا يمكن قراءة عدد دورات المروحة في الدقيقة مرة أخرى — فقط العتبة قابلة للكتابة.",
"install.error.notPkg": "الملفات التي تم إسقاطها ليست ملفات .pkg / .ffpkg / .ffpfs. يتم دعم تنسيقات حزم PS5 فقط هنا.",
kernellog_default_hidden_explainer: "الفئات المخفية الافتراضية هي أنظمة سوني الفرعية الخاصة التي تنبعث باستمرار على كل جهاز PS5 مكسور الحماية بغض النظر عن الحمولة التي يتم تشغيلها. وهي ليست ناتجة عن تحميل ps5. تكون فئات الأعطال و ps5upload وفئات التحميل الأخرى مرئية دائمًا بشكل افتراضي.",
sendpayload_elfldr_convention: "يطابق اصطلاح elfldr — قم بالتغيير فقط إذا كان المحمل يستمع إلى مكان آخر.",
sendpayload_sent_followup: "إذا كان الملف عبارة عن حمولة عاملة، فإن جهاز PS5 الخاص بك يقوم بتشغيله الآن. لا تومض معظم اللوادر بتغيير واضح في واجهة المستخدم — تحقق من إشعار الحمولة أو مؤشر الحالة على وحدة التحكم.",
sendpayload_no_sends_yet: "لا توجد عمليات إرسال حتى الآن. ستظهر عمليات الإرسال الناجحة والفشلة هنا لإعادة التشغيل السريع.",
