upload_mount_after_desc: "بعد أن تهبط الصورة على PS5، تقوم الحمولة بتثبيتها عبر الواجهة الخلفية LVD للنواة. إيقاف التشغيل افتراضيًا — قم بالتشغيل إذا كنت تريد أيضًا إرفاق الصورة بحيث يظهر العنوان في المشغل على الفور.",
upload_mount_readonly_desc: "موصى به. يمنع PS5 من كتابة حفظ البيانات في الصورة (مما يؤدي إلى تلف الملف على القرص في صمت وكسر إعادة التثبيت). قم بإيقاف التشغيل فقط لصور الخدش القابلة للتحرير.",
