installed_kstuff_off_title: "kstuff غير نشط — لن تعمل الألعاب",
installed_kstuff_off_body: "لا يملك الـ payload صلاحية قراءة/كتابة النواة، ما يعني أنّ نقطة دخول jailbreak/kstuff غير محمَّلة. سيفشل تشغيل (وتثبيت) ألعاب fpkg حتى تُحمِّل الجهاز عبر kstuff وتعيد الاتصال.",
