installed_smp_off_body: "يتم تركيب عناوين صور الأقراص من /mnt/shadowmnt بواسطة ShadowMount+. لا يبدو أنه يعمل، لذا لن تُركَّب تلك العناوين أو تعمل. أرسله إلى الجهاز، وانتظر بضع ثوانٍ، ثم تحديث.",
installed_smp_send: "إرسال ShadowMount+",
