upload_streams: "تحميل تدفقات متوازية",
upload_streams_off: "1) أعزب",
upload_streams_hint: "الإعدادات الافتراضية إلى 1 (دفق واحد) — المسار الأكثر استقرارًا، بحد أقصى حوالي 40 ميجابايت/ثانية على وحدات تحكم غير احترافية (حد سلسلة واحدة، وليس شبكتك أو محرك أقراص SSD). يؤدي رفع هذا إلى تحميل مجلدات كبيرة عبر عدة اتصالات في وقت واحد للانتقال بشكل أسرع، ولكن انظر التحذير أدناه. يتم استخدام الحد الأقصى المدعوم من الحمولة المتصلة فقط.",
upload_streams_unsupported: "لا تدعم الحمولة المتصلة تدفقات متعددة حتى الآن — ستستخدم التحميلات دفقًا واحدًا حتى يتم تحديثه.",
upload_streams_unstable: "أسرع، ولكن استخدم بحذر: يعمل أكثر من دفق واحد على عدة عمليات نقل مقابل PS5 في وقت واحد، وعلى بعض وحدات التحكم التي يمكن أن تعطل التحميل الأوسط للحمولة (ثم يتوقف عن الاستجابة حتى تقوم بإعادة تحميله). إذا بدأت التحميلات في الفشل أو انخفضت الحمولة، فاضبط هذا مرة أخرى على 1 — المسار أحادي الدفق هو الأكثر استقرارًا.",
upload_auto_resume: "استئناف التحميلات تلقائيًا بعد الفشل",
upload_auto_resume_hint: "إذا انخفض التحميل في منتصف النقل — في أغلب الأحيان بسبب تعطل حمولة PS5 — فأعد إرسال الحمولة تلقائيًا واستأنف من حيث توقفت، وأعد المحاولة عدة مرات قبل الاستسلام. لا تزال المشاكل المميتة مثل نفاد مساحة PS5 تتوقف على الفور. تشغيل افتراضيًا.",
