reset_hint: "امسح كل أثر محلي لـ PS5Upload وابدأ من جديد: الإعدادات، و PS5s المحفوظة، وسجل النشاط/قائمة الانتظار، وذاكرة التخزين المؤقت للحمولة، وتقارير الأعطال. لا شيء على جهاز PS5 الخاص بك يتأثر. قم بتصدير نسخة احتياطية أعلاه أولاً إذا كنت ترغب في استعادتها.",
