engine_url_hint: "المكان الذي يصل منه التطبيق إلى ps5upload-engine. اتركه على الـ sidecar المحلي الافتراضي، أو وجّهه إلى محرك بعيد/مستضاف ذاتيًا. أعد تشغيل التطبيق بعد التبديل بين المحلي والبعيد.",
err_fs_read_path_not_allowed: "هذا الملف في قسم نظام للقراءة فقط يكون محجوبًا عادةً. فعّل الإعدادات ← «السماح بتنزيل ملفات النظام» للقراءة من ‎/system و‎/system_data والمسارات المحمية الأخرى. هذا يؤثر على التنزيل فقط — الحذف والنقل والكتابة غير مسموحة هناك أبدًا.",
