"pkglib.installAll.what": "ما المقصود بـ«تثبيت الكل»؟",
"pkglib.installAll.whatBody": "يشغّل «تثبيت الكل» كل حزمة جاهزة بالترتيب: اللعبة الأساسية ← التحديثات ← المحتوى الإضافي. وعندما يكون لديك تحديثان لنفس الإصدار (أو حزمتا محتوى إضافي متعارضتان)، استخدم مربع الاختيار في كل صف لتحديد أي منهما ينبغي أن يثبّته هذا الجهاز — واحدة فقط لكل مجموعة. وألغِ التحديد لاستبعاد تلك المجموعة. أما زر «تثبيت» في صف مفرد فيثبّت تلك الحزمة وحدها دائمًا.",
