fs_paste_conflict_body: "هل تريد استبدال {names}؟\n\nيتم دمج المجلدات لا إفراغها: الملفات التي بداخلها ولا تلصقها تبقى كما هي. تُستبدل الملفات ذات الاسم نفسه، ولا يمكن التراجع عن ذلك.",
