"fpkg.about": "اختر مجلد لعبة، أو صورة ربط ‎.exfat أو ‎.ffpkg. يقرأ المحوّل الشجرة، ويتحقق من وجود كل ما تحتاجه حزمة قابلة للتشغيل، ثم يكتب ملف ‎.pkg بتنسيق التصحيح في مجلد الإخراج.",
"fpkg.aboutWhere": "يجري التحويل على الجهاز الذي يشغّل المحرك — هذا الحاسوب أو مضيف Docker أو جهاز Android — لا على المنصة. لا يصل شيء إلى المنصة حتى تثبّت الحزمة — بالبث من هذا الحاسوب، أو برفعها إلى PS5 أولًا.",
"fpkg.aboutSource": "يجب أن يكون المصدر شجرة لعبة مفكوكة التشفير مسبقًا. لا يمكن فك تثبيت نسخة البيع هنا، وسيخبرك الفحص أدناه إن كان هذا ما اخترته.",
"fpkg.aboutFake": "الناتج حزمة مزيفة، لذا يحتاج الجهاز إلى تحميل دعم الحزم المزيفة قبل تثبيتها: kstuff (الإصدار الذي يدعم حزم PS5 المزيفة) وa53_ppr_install_fast.elf وshadowmountplus.elf، بهذا الترتيب. تذكر صفحة «تثبيت حزمة» الأمر نفسه بجوار زر التثبيت.",
"fpkg.aboutChecks": "ما يبحث عنه الفحص",
"fpkg.checkEboot": "ملف eboot.bin في جذر الشجرة — وحدة اللعبة. يجب أن يكون ELF خامًا أو SELF مغلّفًا؛ ولا يمكن إعادة حزم وحدة موقّعة لنسخة البيع.",
"fpkg.checkParam": "وجود sce_sys/param.json وغياب sce_sys/param.sfo — فوجود param.sfo يوجّه مسار التشغيل في الجهاز إلى طريق PS4.",
"fpkg.checkIcons": "معرّف محتوى من 36 حرفًا، والأيقونتان، ووحدة الحقوق sce_sys/about/right.sprx.",
"fpkg.checkDrm": "أن تكون قيمة DRM للحزمة قياسية. القيمة المجانية أو القابلة للترقية تجعل الجهاز يقفل اللعبة؛ تُعاد كتابتها داخل الحزمة فقط، ولا يُمسّ ملفك أبدًا.",
"payloads_essentials_title": "موصى بها مع ps5upload",
"payloads_essentials_body": "إذا كنت تُعدّ جهازًا لأول مرة، فهذه الثلاث تغطي معظم ما يتوقعه ps5upload: kstuff-lite (رقع النواة التي يعتمد عليها معظم البرامج المنزلية)، وShadowMount+ (ربط صور الألعاب من التخزين)، وnanoDNS (إبعاد الجهاز عن مسار تحديثات Sony). كل ما عدا ذلك في هذه القائمة اختياري.",
