"pkglib.url.title": "التثبيت من رابط HTTP(S)",
"pkglib.url.help": "ينزّل هذا الحاسوب الحزمة عبر عدة اتصالات في آن واحد ويمررها إلى PS5 على شبكتك، فيجري النقل بسرعة خطك بدلًا من البث الأحادي الأبطأ للجهاز. لا يُخزَّن شيء على أيٍّ من الجهازين، لذا لا تحتاج لعبة بحجم 100 غيغابايت إلى مساحة حرة. يجب أن يكون الرابط تنزيلًا مباشرًا يدعم نطاقات البايت. أبقِ هذا الحاسوب مستيقظًا حتى ينتهي التثبيت.",
