"library_mount_modal_rw_title": "قراءة وكتابة — يمكنك تعديل هذه الصورة",
"library_mount_modal_rw_body": "عند الربط بهذه الطريقة يمكنك استبدال الملفات أو إضافة محتوى قابل للتنزيل أو تطبيق رقعة نقل لإصدار أقدم — استخدم مستعرض الملفات لتعديل الربط. تُكتب التغييرات مباشرةً في ملف الصورة: قد يجعل التعديل الخاطئ اللعبة غير قابلة للتشغيل ولا يمكن التراجع عنه، فانسخ الصورة أولًا إن كانت مهمة. قد يكتب PS5 أيضًا بيانات الحفظ في صورة مربوطة من تلقاء نفسه.",
