"volumes_mounted_rw": "قراءة وكتابة",
"pkg.patch_loader_not_listening": "تعذّر تطبيق هذا التحديث لأن محمّل الحمولات في PS5 يعمل لكنه لا يقبل الاتصالات على المنفذ 9021، فلم يصل المثبّت المطلوب قط ولم يرَ الجهاز التحديث. لعبتك الأساسية لم تُمس. أعد تحميله من صفحة كسر الحماية — فعملية المحمّل التي قدّمت حمولة من قبل لا تستمر في الاستماع دائمًا. التحديث موجود على PS5 بالفعل، فلا حاجة لرفعه مجددًا — أعد محاولة التثبيت من قائمة الحزم. يمكنك أيضًا تطبيق التحديث من PS5 نفسه: الإعدادات ← النظام ← إعدادات التصحيح ← اللعبة ← Package Installer.",
"pkg.reverify_impossible": "قبل PS5 هذا التثبيت، لكن ps5upload لا يملك ما يتعرّف به على الحزمة المثبّتة، لذا لا يمكنه تأكيده. راجع إشعارات PS5 لمعرفة النتيجة. احتُفظ بالحزمة المجهّزة.",
