"backport_summary": "سيؤدي هذا إلى خفض اللعبة إلى زوج SDK الخاص بـ FW 4 وتثبيت مجموعة المكتبات ({count}) التي تأتي مع {set}. تُثبَّت المجموعة كاملة — خلط المكتبات بين الألعاب هو ما يجعل النقل يفشل في التشغيل.",
