"backport_verify_unpatched_body": "لا يزال ملف eboot يحمل إصدار SDK الأصلي، لذا لا يمكنها العمل على هذا النظام أيًّا كانت المكتبات المثبّتة — المشكلة ليست في مجموعة المكتبات. أعد النقل؛ وإن تكرر ذلك فرقعة SDK لا تُطبَّق.",
"backport_no_larger": "تحتاج هذه اللعبة مكتبات لا توجد في أيٍّ من مجموعاتك. استورد حزمة أكمل، أو افحص جهازًا آخر.",
